package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"testing"
)

// The fixtures are generated by the playable JS kernel. Compare the entire farm,
// including rounding, seeded weather, stock loss, accounts and causal messages.
func TestVineyardGameModelSharedFixtures(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join("..", "minigame", "tests", "fixtures", "v1.json"))
	if err != nil {
		t.Fatal(err)
	}
	var fixtures []struct {
		Name  string `json:"name"`
		Now   int64  `json:"now"`
		Seed  uint32 `json:"seed"`
		Steps []struct {
			Command *vineyardCommand `json:"command"`
			Now     int64            `json:"now"`
		} `json:"steps"`
		Expected json.RawMessage `json:"expected"`
	}
	if err = json.Unmarshal(raw, &fixtures); err != nil {
		t.Fatal(err)
	}
	if len(fixtures) < 4 {
		t.Fatal("missing shared model scenarios")
	}
	for _, fixture := range fixtures {
		t.Run(fixture.Name, func(t *testing.T) {
			state := createVineyardFarm(fixture.Now, fixture.Seed)
			for index, step := range fixture.Steps {
				if step.Command == nil {
					state, err = settleVineyardFarm(state, step.Now)
				} else {
					state, err = applyVineyardAction(state, *step.Command, step.Now)
				}
				if err != nil {
					t.Fatalf("step %d failed: %v", index, err)
				}
			}
			var actual, expected any
			if err = json.Unmarshal([]byte(jsonValue(state)), &actual); err != nil {
				t.Fatal(err)
			}
			if err = json.Unmarshal(fixture.Expected, &expected); err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(actual, expected) {
				t.Fatalf("Go/JS kernel mismatch\nactual=%s\nexpected=%s", jsonValue(actual), jsonValue(expected))
			}
			if !validateVineyardSave(state) {
				t.Fatal("fixture generated invalid state")
			}
		})
	}
}

func TestVineyardGameOfflineSegmentsAndFailedActionsArePure(t *testing.T) {
	initial := createVineyardFarm(100000, 20261012)
	one, err := settleVineyardFarm(initial, initial.LastSettledAt+14*vineyardOfflineDayMS)
	if err != nil {
		t.Fatal(err)
	}
	split, err := settleVineyardFarm(initial, initial.LastSettledAt+7*vineyardOfflineDayMS)
	if err != nil {
		t.Fatal(err)
	}
	split, err = settleVineyardFarm(split, initial.LastSettledAt+14*vineyardOfflineDayMS)
	if err != nil {
		t.Fatal(err)
	}
	one.Version, split.Version = 0, 0
	if !reflect.DeepEqual(one, split) {
		t.Fatal("offline segmentation changes farm outcome")
	}
	before := jsonValue(initial)
	_, err = applyVineyardAction(initial, vineyardCommand{Type: "harvest", PlotID: 1}, initial.LastSettledAt+7*vineyardOfflineDayMS)
	if err == nil || jsonValue(initial) != before {
		t.Fatal("failed action mutates input or succeeds")
	}
	if initial.Plots[0].Moisture != 60 || initial.Day != 0 {
		t.Fatal("settlement mutates caller farm")
	}
}

func TestVineyardGameCropConservationAndUnripeGuard(t *testing.T) {
	state := createVineyardFarm(100000, 20261012)
	state.Day = 70
	state.Plots[0].Brix = 17.5
	state.Plots[0].BerryWeight = 6.5
	state.Plots[0].Damage = 10
	before := jsonValue(state)
	harvested, err := applyVineyardAction(state, vineyardCommand{Type: "harvest", PlotID: 1}, 100000)
	if err != nil {
		t.Fatal(err)
	}
	if jsonValue(state) != before || harvested.Inventory[0].Grade != "A" {
		t.Fatal("harvest purity or grading error")
	}
	_, err = applyVineyardAction(harvested, vineyardCommand{Type: "harvest", PlotID: 1}, 100000)
	if err == nil {
		t.Fatal("harvested same plot twice")
	}
	settled, err := settleVineyardFarm(harvested, 100000+vineyardOfflineDayMS)
	if err != nil {
		t.Fatal(err)
	}
	if settled.Stats.HarvestWeight != settled.Stats.SpoiledWeight+settled.Inventory[0].Weight || settled.Stats.SpoiledWeight <= 0 {
		t.Fatal("inventory spoilage violates conservation")
	}
	sold, err := applyVineyardAction(settled, vineyardCommand{Type: "sell", Channel: "retail"}, settled.LastSettledAt)
	if err != nil {
		t.Fatal(err)
	}
	if sold.Stats.HarvestWeight != sold.Stats.SoldWeight+sold.Stats.SpoiledWeight || len(sold.Inventory) != 0 {
		t.Fatal("sale violates stock conservation")
	}
	_, err = applyVineyardAction(state, vineyardCommand{Type: "harvest", PlotID: 2}, 100000)
	if err == nil {
		t.Fatal("unripe grapes harvested")
	}
}
